import requests

# 1. 這是妳的正確電話號碼 (YOLO 端)
YOLO_API_URL = "http://100.101.167.105:5000/api/v1/predict/trigger"

# 2. 這是他要餵給妳的資料 (格式必須對齊妳程式裡的 PostmanTriggerRequest)
payload = {
    "task_id": "crawl_task_20260522_01",
    "url": "https://example-darkweb-drug-site1.com/item/123",  # 👈 之後用來對齊 DB 撈真圖
    "image_base64": "",
    "priority": 0
}

print("🚀 正在發送任務給 YOLO 分析端...")

try:
    # 3. 狠狠地發送 POST 過去
    response = requests.post(YOLO_API_URL, json=payload, timeout=5)
    
    # 4. 印出妳秒回給他的號碼牌
    print(f"✨ 收到 YOLO 端回應！狀態碼: {response.status_code}")
    print(f"📄 回應內容: {response.json()}")
    
except Exception as e:
    print(f"❌ 派發失敗，請檢查網路或 8000 Port 有沒有開：{e}")